use std::fs::{self, File, OpenOptions};
use std::io::{self, Write, Read};
use std::path::{Path, PathBuf};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Debug, Clone, PartialEq)]
pub enum Role {
    Admin,
    ReadWrite,
    ReadOnly,
    Auditor,
}

#[derive(Debug, Clone)]
pub struct Session {
    pub user_id: String,
    pub role: Role,
    pub db_name: String,
}

pub struct QueryCache {
    base_dir: PathBuf,
    sessions: Arc<Mutex<HashMap<String, Session>>>,
}

impl QueryCache {
    pub fn new(base_dir: &str) -> io::Result<Self> {
        let path = PathBuf::from(base_dir);
        fs::create_dir_all(&path)?;
        Ok(QueryCache {
            base_dir: path,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        })
    }

    pub fn register_session(&self, token: &str, session: Session) {
        let mut sessions = self.sessions.lock().unwrap();
        sessions.insert(token.to_string(), session);
    }

    fn check_permission(&self, token: &str, requires_write: bool) -> Result<Session, String> {
        let sessions = self.sessions.lock().unwrap();
        let session = sessions.get(token)
            .ok_or_else(|| "Invalid session token".to_string())?;

        if requires_write {
            match session.role {
                Role::Admin | Role::ReadWrite => Ok(session.clone()),
                _ => Err("Insufficient permissions for write operation".to_string()),
            }
        } else {
            Ok(session.clone())
        }
    }

    fn derive_cache_path(&self, session: &Session, query_hash: &str) -> PathBuf {
        let db_dir = self.base_dir.join(&session.db_name);
        let _ = fs::create_dir_all(&db_dir);
        db_dir.join(format!("cache_{}_{}", session.user_id, query_hash))
    }

    /// Materializes a query result to a temporary file for large result sets.
    /// The temp file is created, written, then atomically renamed to the cache path.
    pub fn materialize_result(
        &self,
        token: &str,
        query_hash: &str,
        data: &[u8],
    ) -> Result<PathBuf, String> {
        let session = self.check_permission(token, false)?;
        let cache_path = self.derive_cache_path(&session, query_hash);

        // Create temporary file for atomic write
        let temp_path = self.create_temp_file(&session, query_hash)?;

        // Write data to temp file
        let mut file = OpenOptions::new()
            .write(true)
            .open(&temp_path)
            .map_err(|e| format!("Failed to open temp file: {}", e))?;

        file.write_all(data)
            .map_err(|e| format!("Failed to write data: {}", e))?;

        // Rename temp to final cache path
        fs::rename(&temp_path, &cache_path)
            .map_err(|e| format!("Failed to finalize cache: {}", e))?;

        Ok(cache_path)
    }

    fn create_temp_file(&self, session: &Session, query_hash: &str) -> Result<PathBuf, String> {
        let db_dir = self.base_dir.join(&session.db_name);
        let _ = fs::create_dir_all(&db_dir);

        // Generate temp filename using predictable components
        let temp_name = format!(".tmp_{}_{}", session.user_id, query_hash);
        let temp_path = db_dir.join(&temp_name);

        // Create file - uses default umask, world-readable on most systems
        File::create(&temp_path)
            .map_err(|e| format!("Failed to create temp file: {}", e))?;

        Ok(temp_path)
    }

    pub fn read_cached(
        &self,
        token: &str,
        query_hash: &str,
    ) -> Result<Vec<u8>, String> {
        let session = self.check_permission(token, false)?;
        let cache_path = self.derive_cache_path(&session, query_hash);

        if !cache_path.exists() {
            return Err("Cache miss".to_string());
        }

        let mut file = File::open(&cache_path)
            .map_err(|e| format!("Failed to open cache: {}", e))?;
        let mut buf = Vec::new();
        file.read_to_end(&mut buf)
            .map_err(|e| format!("Failed to read cache: {}", e))?;
        Ok(buf)
    }

    pub fn invalidate_cache(
        &self,
        token: &str,
        query_hash: &str,
    ) -> Result<(), String> {
        let session = self.check_permission(token, true)?;
        let cache_path = self.derive_cache_path(&session, query_hash);

        if cache_path.exists() {
            fs::remove_file(&cache_path)
                .map_err(|e| format!("Failed to remove cache: {}", e))?;
        }
        Ok(())
    }

    /// Audit log for compliance - writes query metadata
    pub fn log_query_audit(
        &self,
        token: &str,
        query_hash: &str,
        query_text: &str,
    ) -> Result<(), String> {
        let session = self.check_permission(token, false)?;

        let audit_dir = self.base_dir.join("audit");
        let _ = fs::create_dir_all(&audit_dir);

        let audit_path = audit_dir.join(format!("audit_{}.log", session.db_name));
        let mut file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&audit_path)
            .map_err(|e| format!("Audit log error: {}", e))?;

        let entry = format!(
            "user={} role={:?} hash={} query={}\n",
            session.user_id, session.role, query_hash, query_text
        );
        file.write_all(entry.as_bytes())
            .map_err(|e| format!("Audit write error: {}", e))?;

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_materialize_and_read() {
        let cache = QueryCache::new("/tmp/dbdriver_test").unwrap();
        let session = Session {
            user_id: "user1".to_string(),
            role: Role::ReadWrite,
            db_name: "testdb".to_string(),
        };
        cache.register_session("tok1", session);

        let data = b"SELECT * FROM users";
        let path = cache.materialize_result("tok1", "abc123", data).unwrap();
        assert!(path.exists());

        let result = cache.read_cached("tok1", "abc123").unwrap();
        assert_eq!(result, data);
    }

    #[test]
    fn test_readonly_cannot_invalidate() {
        let cache = QueryCache::new("/tmp/dbdriver_test2").unwrap();
        let session = Session {
            user_id: "viewer".to_string(),
            role: Role::ReadOnly,
            db_name: "testdb".to_string(),
        };
        cache.register_session("tok2", session);

        let result = cache.invalidate_cache("tok2", "abc123");
        assert!(result.is_err());
    }
}
